import sys

def main():
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return
    try:
        balance = int(data[0].strip())
        n = int(data[1].strip())
    except Exception:
        balance = 0
        n = 0
    idx = 2
    for _ in range(n):
        if idx >= len(data):
            break
        line = data[idx].strip()
        idx += 1
        if not line:
            continue
        parts = line.split()
        if len(parts) < 2:
            continue
        op = parts[0].lower()
        try:
            amt = int(parts[1])
        except ValueError:
            continue
        if op == "deposit":
            balance += amt
        elif op == "withdraw":
            balance -= amt
    print(balance)

if __name__ == "__main__":
    main()
